import React from "react";
import MatchingQuestion from "./questions/MatchingQuestion";
import MultipleChoiceQuestion from "./questions/MultipleChoiceQuestion";
import OrderingQuestion from "./questions/OrderingQuestion";
import TrueFalseQuestion from "./questions/TrueFalseQuestion";
import Result from "./Result";
import { useQuiz } from "../hooks/useQuiz";
import { formatAnswer } from "../utils/formatAnswer"; 


function Quiz({ quiz, onRestart }) {
  const {
    currentQuestion,
    userAnswers,
    handleAnswer,
    showFeedback,
    lastCorrectAnswer,
    isCorrectAnswer,
    isQuizComplete,
    resetQuiz,
      retryIncorrectOnly, 
    score,
    total,
  } = useQuiz(quiz.questions); // ⬅️ pass questions into the hook

if (isQuizComplete) {
  const hasIncorrect = userAnswers.some((entry) => !entry.isCorrect);

  return (
    <Result
      userAnswers={userAnswers}
      score={score}
      total={total}
      onRestart={resetQuiz}
      onRetryIncorrect={hasIncorrect ? retryIncorrectOnly : null} // ✅ conditional
    />
  );
}


return (
  <div>
  <div  style={{width: "110%",}}>

    {currentQuestion.image && (
      <img
        src={process.env.PUBLIC_URL + currentQuestion.image}
        alt="Ilustración de la pregunta"
        style={{
          maxWidth: "100%",
          height: "auto",
          marginBottom: "1rem",
          borderRadius: "10px",
        }}
      />
    )}

      <h3  style={{textAlign: "left"}}>{currentQuestion.questionText}</h3>
  </div>

    {currentQuestion.type === "matching" && (
      <MatchingQuestion question={currentQuestion} onSubmit={handleAnswer} />
    )}
    {currentQuestion.type === "multiple-choice" && (
      <MultipleChoiceQuestion question={currentQuestion} onSubmit={handleAnswer} />
    )}
    {currentQuestion.type === "ordering" && (
      <OrderingQuestion question={currentQuestion} onSubmit={handleAnswer} />
    )}
    {currentQuestion.type === "true-false" && (
      <TrueFalseQuestion question={currentQuestion} onAnswer={handleAnswer} />
    )}

    {showFeedback && (
      <div
        style={{
          marginTop: "20px",
          padding: "10px 20px",
          borderRadius: "10px",
          fontWeight: "bold",
          color: "#fff",
          backgroundColor: isCorrectAnswer ? "green" : "red",
          opacity: showFeedback ? 1 : 0,
          transition: "opacity 0.5s ease, transform 0.5s ease",
          transform: showFeedback ? "translateY(0)" : "translateY(-10px)",
        }}
      >
        {isCorrectAnswer ? (
          "✅"
        ) : (
          <div style={{ whiteSpace: "pre-line" }}>
            Respuesta Correcta: <br/><br/>
            {formatAnswer(lastCorrectAnswer)}
          </div>
        )}
        <br />
      </div>
    )}
  </div>
);

}

export default Quiz;
