// utils/formatAnswer.js
export function formatAnswer(answer) {
  if (Array.isArray(answer)) {
    return answer.join(", ");
  }

  if (typeof answer === "object") {
    return JSON.stringify(answer, null, 2); // fallback
  }

  return String(answer);
}
