// PrintableQuiz.jsx
import React, { useRef, useState } from "react";
import html2pdf from "html2pdf.js";
import { shuffleArray } from "../utils/shuffleArray";
import "../styles/PrintableQuiz.css";
import { normalizeQuestions } from "../utils/normalizeQuestions";

function PrintableQuiz({ quiz }) {
  const printRef = useRef(null);
  const [exporting, setExporting] = useState(false);
  const pageTitle = document.title;

  const handleExportPDF = () => {
    setExporting(true);
    const opt = {
      margin: 10,
      filename: `${quiz.title}.pdf`,
      image: { type: "jpeg", quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true },
      jsPDF: { unit: "mm", format: "a4", orientation: "portrait" },
      pagebreak: { mode: ["css", "legacy"] },
    };

    html2pdf()
      .set(opt)
      .from(printRef.current)
      .save()
      .finally(() => setExporting(false));
  };

  // 🔁 Step 1: Normalize (convert true/false to multiple-choice)
  const normalized = normalizeQuestions(quiz.questions);


  const shuffledQuestions = normalized.map((q) => {
    if (q.type === "ordering") {
      const sourceItems = q.correctOrder ?? [];
      return { ...q, shuffledItems: shuffleArray(sourceItems) };
    }
    if (q.type === "multiple-choice") {
      const options = q.answerOptions?.map((opt) => opt.answerText) ?? [];
      //return { ...q, shuffledItems: shuffleArray(options) };
      return { ...q, shuffledItems: options };
    }
    if (q.type === "matching") {
      const colCount = q.correctAnswer?.[0]?.length || 0;
      const columns = Array.from({ length: colCount }, (_, i) => {
        const colItems = [...new Set(q.correctAnswer.map(row => row[i]))];
    // Only shuffle columns from index 1 onward
    return i === 0 ? colItems : shuffleArray(colItems);
      });
      return { ...q, shuffledColumns: columns };
    }
    return q;
  });

  const renderOptionsRow = (items) => (
    <div className="flex-wrap">
      {items.map((item, i) => (
        <div key={i} className="item-box">
          <input type="checkbox" disabled style={{ marginRight: "0.5rem" }} />
          {item}
        </div>
      ))}
    </div>
  );

  return (
    <div className="quiz-container">
      <button onClick={handleExportPDF} disabled={exporting} className="export-button">
        {exporting ? "Generando PDF..." : "Exportar PDF"}
      </button>

      <div ref={printRef} className="pdf-content">
        <h4 className="page-header">{pageTitle}</h4>
        <h1 className="quiz-title">{quiz.title}</h1>

        {shuffledQuestions.map((q, idx) => (
          <div className="question-block" key={idx}>
            <h3 className="question-title">
              {idx + 1}. {q.questionText}
            </h3>

            {["ordering", "multiple-choice"].includes(q.type) &&
              q.shuffledItems &&
              renderOptionsRow(q.shuffledItems)}

            {q.type === "matching" && q.shuffledColumns && (
              <table className="match-table">
                <thead>
                  <tr>
                    {q.columns?.map((col, i) => (
                      <th key={i} className="match-th">{col}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {(() => {
                    const maxRows = Math.max(...q.shuffledColumns.map(col => col.length));
                    return Array.from({ length: maxRows }, (_, r) => (
                      <tr key={r}>
                        {q.shuffledColumns.map((col, ci) => (
                          <td key={ci} className="match-td">{col[r] ?? "\u00A0"}</td>
                        ))}
                      </tr>
                    ));
                  })()}
                </tbody>
              </table>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

export default PrintableQuiz;
