import React, { useEffect, useState } from "react";
import { BrowserRouter as Router, Routes, Route, useNavigate } from "react-router-dom";
import QuizLoader from "./components/QuizLoader";
import { quizIds } from "./data/quizList";
import "./styles/App.css";
import { Helmet } from "react-helmet";
import PrintableHome from "./components/PrintableHome"; // new
import PrintableQuizPage from "./components/PrintableQuizPage"; // new



function Home() {
  const [quizzes, setQuizzes] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    const loadTitles = async () => {
      const loaded = await Promise.all(
        quizIds.map(async (id) => {
          const res = await fetch(`${process.env.PUBLIC_URL}/quizzes/${id}.json`);
          const data = await res.json();
          return { id: data.id, title: data.title, date: data.date, comment: data.comment };
        })
      );
      setQuizzes(loaded);
    };

    loadTitles();
  }, []);

  return (
    <>
    <ul style={{ paddingLeft: "0rem" }}>
      {quizzes.map((quiz) => (
        <li key={quiz.id}>
          <button onClick={() => navigate(`quizzes/${quiz.id}`)}>
            Quiz {quiz.date}<br/>
            {quiz.title} <br/>
            {quiz.comment}
          </button>
        </li>
      ))}
    </ul>


                 </>
  );
}


function App() {
  return (
  <>
        <Helmet>
        <title>Catecumenado San Francisco</title>
        <meta name="description" content="Preguntas para repasar lo estudiado." />
      </Helmet>
    <Router basename={process.env.PUBLIC_URL}>
      <div className="App" style={{ marginBottom: "3rem" }}>
      <a href={process.env.PUBLIC_URL}>
        <img
          src={process.env.PUBLIC_URL + "/logo-titulo.png"}
          alt=""
          style={{
            maxWidth: "100%",
            height: "auto",
            marginBottom: "1rem",
            borderRadius: "10px",
          }}
        />
      </a>
        <h4>Catecumenado San Francisco</h4>

  <Routes>
  <Route path="/" element={<Home />} />
  <Route path="quizzes/:quizId" element={<QuizLoader />} />
  <Route path="printable" element={<PrintableHome />} />
  <Route path="printable/quizzes/:quizId" element={<PrintableQuizPage />} />
</Routes>
      
      </div>
    </Router>


        </>
  );
}


export default App;
